package ru.kryuch.krtg.searcher.helper;import jakarta.servlet.http.HttpServletResponse;import lombok.extern.slf4j.Slf4j;import org.springframework.stereotype.Component;import java.io.IOException;import java.io.PrintWriter;@Component@Slf4jpublic class ExportHelper {	public void export(String text, HttpServletResponse response) {		try {			response.setContentType("text/plain");			response.setCharacterEncoding("UTF-8");			response.setHeader("Content-Disposition", "attachment; filename=\"exportedKrrgChats.txt\"");			PrintWriter writer = response.getWriter();			writer.write(text);			writer.flush();		} catch (Exception e) {			log.error("Ошибка при экспорте чатов", e);			response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);			try {				response.getWriter().write("Ошибка при экспорте: " + e.getMessage());			} catch (IOException ex) {				log.error("Ошибка записи ошибки", ex);			}		}	}}